    random.seed(seed)
    cur=''.join(random.choice('ACGU') for _ in range(len(unit_target)))
    cd=dist(cur)
    for _ in range(8000):
        c=list(cur)
        for _ in range(random.choice([1,1,2])):
            i=random.randrange(len(c)); c[i]=random.choice('ACGU')
        c=''.join(c); d=dist(c)
        if d<cd or (d==cd and random.random()<0.4):
            cur,cd=c,d
